from fractions import Fraction

def calculate_A(a_list):
    n = len(a_list)
    A = 0
    for x in range(n):
        prod_val = Fraction(1)
        for y in range(n):
            if x == y:
                continue
            prod_val *= Fraction(a_list[x] * a_list[y] - 1, a_list[x] - a_list[y])
        A += prod_val
    return A

for i in range(1, 5):
    a_list = [2**j for j in range(1, i+2)]
    print(f"i={i}, a={a_list}, A={calculate_A(a_list)}")

